// === Tab: mySketch ===
// For the #WCCChallenge, theme: "spiral".
// This paper lays out the math here in terms simple enough that I can (just barely) follow along!
// https://www.mat.uc.pt/~picado/conchas/eng/article.pdf
// For each shell, this sketch generates a unique 3D cross-section, then extrudes the cross-section along a helical path.
// Amazingly, such seemingly different shells all result from small variations in the cross-section and spiral path. 

var e = 2.71828;
var sections = 600;
var section;
var lpos, tlpos;
var orbit, torbit;
var swidth, sheight;
var cutx, cuty;
var orbits, ovel;
var xstretch, ystretch, tilt, bend;
var zoom = 1;
var tzoom, ozoom;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	ozoom = height / 600;
	lpos = createVector(0, 0);
	tlpos = createVector(0, 0);
	orbit = createVector(0, 0);
	torbit = createVector(0, -HALF_PI);
	makeHTML();
	chooseInitial();
	tzoom = ozoom;
}

function draw() {
	tlpos.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2;
	tlpos.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2;
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 150) {
		torbit.x += movedX / 100;
		torbit.y -= movedY / 200;
	}
	lpos.lerp(tlpos, 0.05);
	orbit.lerp(torbit, 0.1);
	zoom = lerp(zoom, tzoom, 0.1);
	background(0);
	ambientLight(100);
	pointLight(122, 61, 67, 2 * lpos.x, lpos.y / 2, lpos.y);
	noStroke();
	specularMaterial(255);
	drawPreview();
	scale(zoom);
	rotateY(orbit.x);
	rotateX(orbit.y);
	rotateY(4 * PI / 3);
var a = 0;
var C = 1
var y = -200 * ystretch;
var layers = min(frameCount * 5, sections);
	for (let i = 0; i < layers; i++) {
		var a = map(i, 0, sections, 0, 8 * TAU);
var r = C * (e ** (a * (1 / tan(PI / 2.13)))); //Natural log magic!
		y += ystretch * r / (sections / orbits);
		push();
		translate(0, ystretch * y, 0);
		rotateY(-ovel * a + HALF_PI);
		rotateZ(tilt);
		translate(xstretch * r, 0, 0);
		rotateY(bend);
		scale(map(r, 0, 120, 0, 1.5));
		rotateY(PI);
		model(section);
		pop();
	}
}

function drawPreview() {
	push();
	translate(-width / 2 + 75, height / 2 - (sheight + 50), 0);
	rotateY(frameCount / 60);
	model(section);
	pop();
}

function keyPressed() {
	if (keyCode == 32) restoreTilt();
}

function restoreTilt() {
	torbit.x = 0;
	torbit.y = -HALF_PI;
	tzoom = ozoom;
	setTimeout(tiltBack, 2500);
}

function mouseWheel(event) {
	tzoom += event.delta / 100;
}

function tiltBack() {
	torbit.y = PI / 12;
}

function chooseInitial() {
var pick = floor(random(buttons.length));
	switch (pick) {
		case 0:
			drawClam();
			break;
		case 1:
			drawNautilus();
			break;
		case 2:
			drawOlive();
			break;
		case 3:
			drawPeriwinkle();
			break;
		case 4:
			drawTurritella();
			break;
		case 5:
			drawWhelk();
			break;
	}
}

